import { existsSync, mkdirSync, copyFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';

const files = {
  "src/views/Users.tsx": "",
  "src/styles.css": "",
  "RELEASE_NOTES_0.10A.md": ""
};
const root = process.cwd();
const required = ['package.json', 'src/views/Users.tsx', 'src/styles.css'];
for (const relative of required) {
  if (!existsSync(join(root, relative))) {
    console.error(`CHYBA: V projekte chyba ${relative}. Spustite instalator v koreni projektu vedla package.json.`);
    process.exit(1);
  }
}

const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const backupRoot = join(root, `backup-before-fix-010a-${stamp}`);
for (const relative of ['src/views/Users.tsx', 'src/styles.css']) {
  const source = join(root, relative);
  const target = join(backupRoot, relative);
  mkdirSync(dirname(target), { recursive: true });
  copyFileSync(source, target);
}

for (const [relative, encoded] of Object.entries(files)) {
  const target = join(root, relative);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, Buffer.from(encoded, 'base64'));
}

const users = Buffer.from(files['src/views/Users.tsx'], 'base64').toString('utf8');
const styles = Buffer.from(files['src/styles.css'], 'base64').toString('utf8');
const checks = [
  ['Users wrapper', users.includes('users-table-shell')],
  ['Responsive table fix', styles.includes('Fix 0.10A')],
  ['Horizontal scrolling', styles.includes('overflow:auto')],
  ['Sticky actions', styles.includes('position:sticky') && styles.includes('right:0')],
  ['CMDB/ITSM table protection', styles.includes('.cmdb-table-shell') && styles.includes('.helpdesk-table-shell')],
];
for (const [label, ok] of checks) console.log(`${ok ? 'OK' : 'CHYBA'}: ${label}`);
if (checks.some(([, ok]) => !ok)) process.exit(1);
console.log('HOTOVO: Fix 0.10A bol nainstalovany. Zaloha:', backupRoot);
console.log('Dalsi krok: npm run dev a potom Ctrl+F5 v nahlade.');
